(()=>{'use strict';const embedded=parent!==window;document.documentElement.classList.add('lab-dark');if(embedded){document.documentElement.classList.add('lab-embedded');const actions=document.querySelector('body>.top .top-actions');if(actions){const bar=document.createElement('div');bar.className='tool-actions-bar';bar.append(actions);document.body.prepend(bar);}return;}const links=[['/','대시보드','▦'],['/lab/','배치 · DPS','⌖'],['/units/','초마신 도감','♧'],['/dealer-tiers/','딜러 티어','▥'],['/stages/','스테이지 분석','◎'],['/wall/','성벽 조합','♜'],['/rankings/','솔로 랭킹','▥'],['/updates/','업데이트','↗']];const aside=document.createElement('aside');aside.className='lab-sidebar';const brand=document.createElement('a');brand.className='lab-brand';brand.href='/';brand.innerHTML='<img src="/logo.svg" alt="스택 연구소 기존 로고"><span>스택 연구소<small>STACK LAB</small></span>';aside.append(brand);const nav=document.createElement('nav');nav.setAttribute('aria-label','주요 연구 도구');for(const [href,label,icon]of links){const a=document.createElement('a');a.href=href;if(location.pathname===href){a.className='active';a.setAttribute('aria-current','page');}const glyph=document.createElement('span');glyph.textContent=icon;glyph.setAttribute('aria-hidden','true');a.append(glyph,document.createTextNode(label));nav.append(a);}aside.append(nav);const caption=document.createElement('p');caption.className='sidebar-caption';caption.innerHTML='더 깊이,<br>더 강한 덱을 위해.<small>스택 연구소와 함께.</small>';aside.append(caption);document.body.prepend(aside);const top=document.createElement('div');top.className='lab-topbar';top.innerHTML='<span class="lab-breadcrumb">WORKSPACE <i>/</i> <b>OVERVIEW</b></span><div class="lab-top-actions"><a href="/units/" class="lab-search">⌕ <span>초마신 · 보석을 연구해 보세요</span></a><a href="/updates/" aria-label="업데이트 확인">♧</a><span class="lab-local-label">STACK LAB</span></div>';document.body.insertBefore(top,aside.nextSibling);const actions=document.querySelector('body>.top .top-actions');if(actions)top.querySelector('.lab-top-actions').append(actions);const sync=()=>{for(const a of nav.querySelectorAll('a')){const active=new URL(a.href).pathname===location.pathname;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}top.querySelector('.lab-breadcrumb b').textContent=location.pathname==='/'?'OVERVIEW':links.find(([href])=>href===location.pathname)?.[1]||'WORKSPACE';};new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['class']});window.addEventListener('popstate',sync);window.addEventListener('stack-lab:navigate',sync);sync();})();
